-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.caller_is_owner()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.admin_emails a
     where a.owner and a.email = lower(trim(auth.jwt() ->> 'email')));
$function$;

grant execute on function public.caller_is_owner() to service_role;
